$_MODULE['<{sudemi}prestashop>sudemi_1bd983391f0e9675405614baf1ed990c'] = 'sudemi odrzuciło żądania z tej witryny: ten sklep jest połączony z sudemi pod innym adresem (%s). Jeśli ta witryna jest kopią testową (staging) lub przywróconą kopią zapasową, odłącz tutaj sudemi. Jeśli sklep przeniósł się pod ten adres, połącz go ponownie.';
$_MODULE['<{sudemi}prestashop>sudemi_ce1ed32e41d97b80d80b33148f53f789'] = 'sudemi odrzuciło żądania z tej witryny: ten sklep jest połączony z sudemi pod innym adresem. Jeśli ta witryna jest kopią testową (staging) lub przywróconą kopią zapasową, odłącz tutaj sudemi. Jeśli sklep przeniósł się pod ten adres, połącz go ponownie.';
$_MODULE['<{sudemi}prestashop>sudemi_432e26275e5095d41313deeb350c7ea2'] = 'Najpierw połącz ten sklep z sudemi.';
$_MODULE['<{sudemi}prestashop>sudemi_a473565a143cf3cdb01895753a94ccab'] = 'Zwrot przyjęty. Kupujący dostanie informację, że ma odesłać produkt. Gdy produkt wróci, zwróć pieniądze za to zamówienie jak zwykle (status Zwrot pieniędzy albo korekta dla części): zwrot trafia do kupującego przez sudemi i zamyka zgłoszenie.';
$_MODULE['<{sudemi}prestashop>sudemi_cb2539cea371b3e5736c3444acbfccf9'] = 'Zwrot odrzucony. sudemi pokaże kupującemu Twój powód.';
$_MODULE['<{sudemi}prestashop>sudemi_8af7448f2470dbdf3e3c52b23b771e9d'] = 'To zgłoszenie zwrotu miało już odpowiedź (w sudemi albo od sudemi po terminie). Niczego nie zmieniono.';
$_MODULE['<{sudemi}prestashop>sudemi_9fba5e140e3eeeef1fb479338a5f0a00'] = 'sudemi nie ma otwartego zgłoszenia zwrotu dla tego zamówienia. Usunięto je z listy.';
$_MODULE['<{sudemi}prestashop>sudemi_77045abe2681e10ec8585af1568a531d'] = 'Aby odrzucić zwrot, podaj powód. Kupujący go zobaczy.';
$_MODULE['<{sudemi}prestashop>sudemi_f56cb5d64a1b05252377f64a8a6995b3'] = 'sudemi nie przyjęło tej odpowiedzi. Odrzucenie wymaga powodu; sprawdź go i spróbuj ponownie.';
$_MODULE['<{sudemi}prestashop>sudemi_98cb3df4ed609dceaddc55efce570395'] = 'Zgłoszenia zwrotu';
$_MODULE['<{sudemi}prestashop>sudemi_0eba7b42b6c53cdc949279b9d1e6ac3c'] = 'Kupujący chcą zwrócić te dostarczone zamówienia. Odpowiedz na każde przed terminem odpowiedzi: przyjmij albo odrzuć z podaniem powodu (kupujący go zobaczy). Bez odpowiedzi decyzję podejmuje sudemi. Po przyjęciu zwróć pieniądze za zamówienie, gdy produkt wróci.';
$_MODULE['<{sudemi}prestashop>sudemi_626c7431b351c533751339ea2f7f6c5c'] = 'Brak otwartych zgłoszeń zwrotu.';
$_MODULE['<{sudemi}prestashop>sudemi_63ab309ecf9b1ba9d3ced8c587fb6051'] = 'Powód podany przez kupującego';
