$_MODULE['<{sudemi}prestashop>sudemi_79b0f6d2990d85e793870809766304aa'] = 'Kupujący chce zwrócić to zamówienie. Przyjmij albo odrzuć z podaniem powodu (kupujący go zobaczy). Bez odpowiedzi do poniższej daty decyzję podejmuje sudemi. Po przyjęciu zwróć pieniądze za to zamówienie, gdy produkt wróci.';
$_MODULE['<{sudemi}prestashop>sudemi_e00c83de07e4077ccea2be7df460c7de'] = 'Synchronizacja katalogu została uruchomiona i działa w tle; katalog zostanie wysłany w ciągu kilku minut.';
$_MODULE['<{sudemi}prestashop>sudemi_a503ac4f79fc663865bf1a2875313402'] = 'Kupujący zapłacił';
$_MODULE['<{sudemi}prestashop>sudemi_6f005e6f52b7a8f6fa860f7e8fbddfc8'] = 'Waluta sklepu';
$_MODULE['<{sudemi}prestashop>sudemi_25f30b7a6c8492438cff249034c6a8ad'] = 'Kupujący płacą w tej walucie, a zamówienia, które wysyła Ci sudemi, są w tej walucie. Wypłata z sudemi jest w euro; przy każdej innej walucie operator płatności Stripe pobiera z wypłaty opłatę za przewalutowanie w wysokości około 2 procent.';
$_MODULE['<{sudemi}prestashop>sudemi_1d75c6794f7c6f15f9d20716a7534e15'] = 'sudemi nie przyjmuje płatności w %1$s, więc Twoje produkty nie są pokazywane kupującym. sudemi przyjmuje te waluty: %2$s. Wybierz jedną z nich jako domyślną walutę tego sklepu, a potem wyślij katalog ponownie.';
$_MODULE['<{sudemi}prestashop>sudemi_a0e397dee2f1c5834ab1d445aec6cdc6'] = 'Ten sklep sprzedaje teraz w %1$s, ale sudemi ma nadal %2$s. Wyślij katalog ponownie, aby kupujący widzieli właściwe ceny.';

